pub fn mt19937(seed: u32) -> Vec<u32> {
    // MT19937 uses a state vector of length 624
    let mut state = vec![0u32; 624];
    state[0] = seed;
    for i in 0..623 {
        // Compute the recurrence:
        // state[i+1] = 1812433253 * (state[i] ^ (state[i] >> 30)) + (i + 1)
        let x = state[i] ^ (state[i] >> 30);
        state[i + 1] = x
            .wrapping_mul(1812433253)
            .wrapping_add((i as u32) + 1);
    }
    state
}

